package me.neobliz1.ecomonitoring.platform.history.infrastructure.adapter.inbound.grpc;import static me.neobliz1.ecomonitoring.platform.common.util.PlatformCommonUtils.expandRequestSpatialBoxByTier;import static me.neobliz1.ecomonitoring.platform.history.domain.model.constant.HistoricalCacheConstants.BUCKETS_GLOBAL_REGION;import static me.neobliz1.ecomonitoring.platform.history.domain.model.constant.HistoricalCacheConstants.QUERIES_GLOBAL_REGION;import io.github.neobliz1.validproto.annotation.ValidProto;import io.github.neobliz1.validproto.annotation.ValidatedProto;import io.grpc.Status;import io.grpc.StatusRuntimeException;import io.grpc.stub.StreamObserver;import lombok.RequiredArgsConstructor;import lombok.extern.slf4j.Slf4j;import me.neobliz1.ecomonitoring.platform.history.domain.model.dto.WeatherMapBucketCacheDto;import me.neobliz1.ecomonitoring.platform.history.domain.model.entity.WeatherGridCellLayer;import me.neobliz1.ecomonitoring.platform.history.domain.model.entity.WeatherMapBucket;import me.neobliz1.ecomonitoring.platform.history.domain.port.inbound.HistoricalDataConvertService;import me.neobliz1.ecomonitoring.platform.history.domain.port.outbound.HistoricalQueryRepository;import me.neobliz1.ecomonitoring.platform.history.infrastructure.adapter.inbound.grpc.record.SpatialQueryKey;import me.neobliz1.ecomonitoring.platform.model.exception.L1CacheNotAvailableException;import me.neobliz1.ecomonitoring.platform.shared.contracts.proto.map.GridCellLayers;import me.neobliz1.ecomonitoring.platform.shared.contracts.proto.map.WeatherMap;import org.jspecify.annotations.NonNull;import org.springframework.cache.Cache;import org.springframework.cache.CacheManager;import weather.history.HistoryServiceGrpc;import weather.history.SpatialBoxRequest;import java.util.List;import java.util.Map;import java.util.Optional;import java.util.UUID;import java.util.stream.Collectors;@Slf4j@ValidatedProto@RequiredArgsConstructorpublic class HistoricalExternalCommunicationObserver extends HistoryServiceGrpc.HistoryServiceImplBase {    private final HistoricalQueryRepository historicalQueryRepository;    private final HistoricalDataConvertService weatherMapConverter;    private final CacheManager springL1CacheManager;    private static void proceedFailedResponse(StreamObserver<WeatherMap> responseObserver, Exception e, String errMsg) {        Status status = Status.INTERNAL;        if(e instanceof StatusRuntimeException && e.getMessage().contains(Status.Code.NOT_FOUND.name())) {            status = Status.NOT_FOUND;        }        log.error(errMsg);        responseObserver.onError(status                .withDescription(errMsg)                .withCause(e)                .asRuntimeException());    }    private static void proceedSuccessResponse(StreamObserver<WeatherMap> responseObserver, WeatherMap weatherMap) {        responseObserver.onNext(weatherMap);        responseObserver.onCompleted();    }    @Override    public void findFilteredGridDataBySpatialBox(@ValidProto SpatialBoxRequest request, StreamObserver<WeatherMap> responseObserver) {        long timestampBucketInMillis = request.getTimestampBucket();        double minLat = request.getMinLat();        double maxLat = request.getMaxLat();        double minLon = request.getMinLon();        double maxLon = request.getMaxLon();        if(log.isDebugEnabled()) {            log.debug("GRPC request: {} [{}#{}#{}#{}] has been received and is processing.",                    timestampBucketInMillis, minLat, maxLat, minLon, maxLon);        }        getGridDataBySpatialBox(responseObserver, request);    }    private void getGridDataBySpatialBox(@NonNull StreamObserver<WeatherMap> responseObserver, @NonNull SpatialBoxRequest request) {        try {            SpatialQueryKey queryKey = new SpatialQueryKey(                    request.getTimestampBucket(),                    request.getTimeIntervalInMinutes(),                    request.getMinLat(),                    request.getMaxLat(),                    request.getMinLon(),                    request.getMaxLon()            );            Cache grpcQueryCache = getGrpcQueryCache();            WeatherMap cachedResponse = grpcQueryCache.get(queryKey, WeatherMap.class);            if(cachedResponse!=null) {                if(log.isDebugEnabled()) {                    log.debug("Mux Performance Hit! Serving complete WeatherMap Protobuf array directly from shared L1 cache memory.");                }                proceedSuccessResponse(responseObserver, cachedResponse);                return;            }            WeatherMap weatherMap = getWeatherMap(request);            if(log.isDebugEnabled()) {                log.debug("WeatherMap successfully built for request [{}]: Found {} unique grid cell(s).", queryKey, weatherMap.getGridCellsCount());            }            grpcQueryCache.put(queryKey, weatherMap);            proceedSuccessResponse(responseObserver, weatherMap);        } catch(StatusRuntimeException e) {            proceedFailedResponse(responseObserver, e,                    String.format("Spatial box lookup failed with explicit status: %s", e.getStatus()));        } catch(Exception e) {            proceedFailedResponse(responseObserver, e,                    String.format("Unexpected error processing spatial box request: %s, cause: %s", e.getMessage(), e.getCause().getMessage()));        }    }    private @NonNull WeatherMap getWeatherMap(@NonNull SpatialBoxRequest request) {        SpatialBoxRequest expandedRequest = request;        List<WeatherGridCellLayer> weatherGridCells = List.of();        for(int i = 0; i<4; i++) {            weatherGridCells = getWeatherGridCellMetrics(expandedRequest);            if(!weatherGridCells.isEmpty()) {                break;            }            expandedRequest = expandRequestSpatialBoxByTier(expandedRequest, i);        }        if(weatherGridCells.isEmpty()) {            throw Status.NOT_FOUND                    .withDescription("No grid metrics found within the requested time or any past historical buckets.")                    .asRuntimeException();        }        Map<String, GridCellLayers> cellLayersMap = weatherGridCells.stream()                .collect(Collectors.toMap(                        WeatherGridCellLayer::getGeohash,                        weatherMapConverter::convertWeatherGridCellsToWeatherMap,                        (existing, replacement) -> existing                ));        return WeatherMap.newBuilder()                .setIntervalMinutes(request.getTimeIntervalInMinutes())                .setTimestampBucket(request.getTimestampBucket())                .putAllGridCells(cellLayersMap)                .build();    }    private @NonNull Cache getGrpcQueryCache() {        Cache grpcQueryCache = springL1CacheManager.getCache(QUERIES_GLOBAL_REGION);        if(grpcQueryCache==null) {            throw new L1CacheNotAvailableException(QUERIES_GLOBAL_REGION);        }        return grpcQueryCache;    }    private @NonNull List<WeatherGridCellLayer> getWeatherGridCellMetrics(@NonNull SpatialBoxRequest request) {        UUID bucketId = resolveBucketIdWithCache(request);        List<WeatherGridCellLayer> weatherGridCells = List.of();        if(bucketId!=null) {            weatherGridCells = historicalQueryRepository.findByBucketIdAndSpatialBox(bucketId, request);        }        List<WeatherMapBucket> pastBuckets = historicalQueryRepository.findAllPastBuckets(request);        while(weatherGridCells.isEmpty() && !pastBuckets.isEmpty()) {            WeatherMapBucket pastBucket = pastBuckets.getFirst();            UUID pastBucketId = pastBucket.getId();            log.info("Evaluating past bucket ID: {} from timestamp: {}", pastBucketId, pastBucket.getTimestampBucket());            weatherGridCells = historicalQueryRepository.findByBucketIdAndSpatialBox(pastBucketId, request);            pastBuckets.removeFirst();        }        return weatherGridCells;    }    private UUID resolveBucketIdWithCache(@NonNull SpatialBoxRequest request) {        UUID deterministicId = UUID.nameUUIDFromBytes((String.valueOf(request.getTimestampBucket())                +request.getTimeIntervalInMinutes()).getBytes());        Cache bucketL1Cache = springL1CacheManager.getCache(BUCKETS_GLOBAL_REGION);        if(bucketL1Cache==null) {            throw new L1CacheNotAvailableException(BUCKETS_GLOBAL_REGION);        }        WeatherMapBucketCacheDto cachedBucket = bucketL1Cache.get(deterministicId, WeatherMapBucketCacheDto.class);        if(cachedBucket!=null) {            return cachedBucket.id();        }        Optional<WeatherMapBucket> optionalWeatherMapBucket = historicalQueryRepository.findByTimestampBucketAndIntervalMinutes(request);        if(optionalWeatherMapBucket.isEmpty()) {            return null;        }        WeatherMapBucket weatherMapBucket = optionalWeatherMapBucket.get();        UUID bucketId = weatherMapBucket.getId();        WeatherMapBucketCacheDto dtoToCache = new WeatherMapBucketCacheDto(                bucketId,                weatherMapBucket.getTimestampBucket(),                weatherMapBucket.getIntervalMinutes(),                weatherMapBucket.getVersion()        );        bucketL1Cache.put(deterministicId, dtoToCache);        return bucketId;    }}